    const worldTask = text.match(/^(?:(?:which|what) (?:os|world|environment|part of curioid) (?:should i use|would i use|is best for|is for|handles)|(?:what|which) (?:app|tool) (?:should i use|is best for)|what (?:should|can) i use (?:for|to)|where (?:should i go|can i go) for|which world handles|which os handles)\s+(.+?)[?.!]*$/);
