    const dayUpdate = text.match(/^(?:today|my day|the day) (?:has been|was|is) (rough|hard|difficult|awful|horrible|bad|amazing|great|wonderful|okay|fine|long|exhausting|stressful)\b/) || text.match(/^(?:i had|ive had|i've had|i am having|im having|i'm having) (?:a )?(rough|hard|difficult|awful|horrible|bad|amazing|great|wonderful|okay|fine|long|exhausting|stressful) day\b/);
