    if(!tombstone||typeof tombstone!=='object'||Array.isArray(tombstone))throw new Error('A local record deletion marker has an invalid format. The record list was not treated as complete.');
    if(tombstone.hideAll===true){if(tombstone.visibleRevision!=null&&typeof tombstone.visibleRevision!=='string')throw new Error('A local record deletion marker has an invalid revision.');return tombstone.visibleRevision==null||(record.storageRevision??null)!==tombstone.visibleRevision;}
    if(Object.prototype.hasOwnProperty.call(tombstone,'storageRevision'))return (tombstone.storageRevision??null)===(record.storageRevision??null);
