    for(let i=0;i<length;i++){let key;try{key=localStorage.key(i);}catch(error){throw new Error(`CURIOID could not enumerate private local records: ${error?.message||'storage is unavailable'}.`);}if(key&&key.startsWith(CURIOID_LOCAL_SERVICE_PREFIX))keys.push(key);}
