      const problems=kernelArtifactRecordProblems(artifact);
      add('Recognized artifact format',artifact.format==='curioid-artifact'&&artifact.schemaVersion===1);
      add('Required metadata and content descriptor',problems.length===0,problems.join('; '));
      add('Content size within Kernel limit',Number.isFinite(artifact.content?.size)&&artifact.content.size>=0&&artifact.content.size<=CURIOID_KERNEL_ARTIFACT_LIMIT);
      add('Content kind recognized',['json','text','blob'].includes(artifact.content?.kind));
