  async function kernelRebuildArtifactIndex(onProgress = null) {
    const progressCallback = typeof onProgress === 'function' ? onProgress : null;
    let lastProgress = 0;
    const reportProgress = (count, force = false) => {
      if (!progressCallback || count <= lastProgress || (!force && count - lastProgress < 100)) return;
      lastProgress = count;
      try { progressCallback(Object.freeze({ processed: count })); } catch (_) {}
    };
    return kernelTransactionExisting(['artifacts','artifact-index'],'readwrite',tx=>new Promise((resolve,reject)=>{
      const artifacts=tx.objectStore('artifacts'),index=tx.objectStore('artifact-index');
      let rebuilt=0,settled=false;
      const fail=error=>{
        if(settled)return;
        settled=true;
        reject(error instanceof Error?error:new Error('Artifact index rebuild failed.'));
      };
      // Rebuild directly from a cursor instead of materialising the complete
      // source catalogue with getAll(). The clear and every replacement stay
      // in one read-write transaction, so a bad source row or failed write
      // rolls the whole rebuild back and preserves the previous index.
      const clearRequest=index.clear();
      clearRequest.onerror=()=>fail(clearRequest.error||new Error('Could not clear the derived artifact index.'));
      const cursorRequest=artifacts.openCursor();
      cursorRequest.onerror=()=>fail(cursorRequest.error||new Error('Could not read source artifacts for index rebuild.'));
      cursorRequest.onsuccess=()=>{
        if(settled)return;
        const cursor=cursorRequest.result;
        if(!cursor){
          settled=true;
          reportProgress(rebuilt, true);
          resolve({rebuilt,invalid:0,completedAt:new Date().toISOString()});
          return;
        }
        const item=cursor.value;
        const problems=kernelArtifactRecordProblems(item);
        if(problems.length){
          fail(new Error(`Index rebuild stopped at source artifact ${String(item?.id||'(unknown)').slice(0,96)} because its structure is invalid. The previous index was preserved. Review the record before retrying.`));
          try{tx.abort();}catch(_){}
          return;
        }
        const putRequest=index.put(kernelArtifactIndex(item));
        putRequest.onerror=()=>fail(putRequest.error||new Error('Could not write a derived artifact index entry.'));
        rebuilt++;
        reportProgress(rebuilt);
        try{cursor.continue();}catch(error){fail(error);try{tx.abort();}catch(_){}}
      };
    }));
  }

