  async function kernelSaveLocalDataSafetyBackup(ownerExperienceId, records, reason='before-change') {
    const owner=kernelLocalValidateOwner(ownerExperienceId),rows=Array.isArray(records)?records:[];
    if(!rows.length)return null;
    const createdAt=new Date().toISOString(),bundle={format:'curioid-local-data',schemaVersion:1,ownerExperienceId:owner,exportedAt:createdAt,backupReason:String(reason).slice(0,48),records:rows};
    const serialized=JSON.stringify(bundle),byteLength=new TextEncoder().encode(serialized).byteLength;
    if(byteLength>8*1024*1024)throw new Error('The automatic local-data safety backup exceeds the 8 MB limit. Export the affected data manually before changing it.');
    const stamp=createdAt.replace(/[:.]/g,'-'),safeReason=String(reason).toLowerCase().replace(/[^a-z0-9-]+/g,'-').replace(/^-|-$/g,'').slice(0,32)||'before-change';
    const name=`curioid-${owner}-${safeReason}-${stamp}.curioidlocalbackup`,blob=new Blob([serialized],{type:'application/json'});
    let saved=null;
    try {
      saved=await curioidVault.save(blob,name,{source:'CURIOID automatic local-data safety backup'});
      if(!saved||saved.sessionOnly)throw new Error('The backup was stored only for this browser session. A durable backup is required, so the change was stopped.');
      const stored=await curioidVault.get(saved.id);
      if(!stored?.blob||Number(stored.size)!==byteLength)throw new Error('The saved backup could not be read back with its original size.');
      const storedText=await stored.blob.text();
      if(storedText!==serialized)throw new Error('The saved backup failed its exact read-back verification.');
      window.dispatchEvent(new CustomEvent('curioid:vault-notice',{detail:{message:`Safety backup saved and verified: ${saved.name} (${rows.length} record${rows.length===1?'':'s'}).`}}));
      return {id:saved.id,name:saved.name,recordCount:rows.length,size:byteLength,createdAt};
    } catch(error) {
      if(saved?.id)try{await curioidVault.remove(saved.id);}catch(_){}
      throw new Error(`CURIOID could not create and verify a durable safety backup (${String(error?.message||error).slice(0,220)}). No local-data change was made.`);
    }
  }
  function kernelWithLocalRecordOwnerLock(ownerExperienceId, operation) {
    const locks = typeof navigator !== 'undefined' ? navigator.locks : null;
    if (!locks || typeof locks.request !== 'function') {
      return Promise.reject(new Error('Safe multi-tab local data coordination is unavailable in this browser context. Open CURIOID over HTTPS in a modern browser with Web Locks support; no changes were made.'));
    }
    return locks.request(`curioid-kernel-local-records:${ownerExperienceId}`, { mode: 'exclusive' }, operation);
  }
  async function kernelSaveAdapterSafetyBackup(ownerExperienceId, adapter, artifactType) {
    const owner=kernelValidId(ownerExperienceId,'Adapter owner');
    if(kernelAdapters.get(owner)!==adapter||kernelExperiences.get(owner)?.lifecycleId!==adapter?.providerLifecycleId)throw new Error('The native adapter changed before its recovery export. No destructive import was started.');
    const exported=await CurioidKernel.exportWithAdapter(owner);
    if(kernelAdapters.get(owner)!==adapter||kernelExperiences.get(owner)?.lifecycleId!==adapter?.providerLifecycleId)throw new Error('The native adapter changed while its recovery export was running. No destructive import was started.');
    const matching=exported.filter(item=>item.type===artifactType);
    if(!matching.length){if(!exported.length)return null;throw new Error('The current project adapter did not provide a recovery copy matching the replacement type. The import was stopped before changing the project.');}
    const createdAt=new Date().toISOString(),stamp=createdAt.replace(/[:.]/g,'-');
    const serialized=JSON.stringify(matching.length===1?matching[0].data:matching.map(item=>({type:item.type,title:item.title,data:item.data,metadata:item.metadata})));
    const byteLength=new TextEncoder().encode(serialized).byteLength;
    if(byteLength>CURIOID_KERNEL_ARTIFACT_LIMIT)throw new Error('The current project is too large for an automatic pre-import safety backup. Export the project manually before replacing it.');
    const extension=artifactType==='umbra/project'?'.umbra':'.json';
    const filename=`${owner}-before-replacement-${stamp}${extension}`;
    const blob=new Blob([serialized],{type:'application/json'});
    let saved=null;
    try{
      saved=await curioidVault.save(blob,filename,{source:'CURIOID automatic adapter safety backup'});
      if(!saved||saved.sessionOnly)throw new Error('The backup was stored only for this browser session. A durable backup is required, so the replacement was stopped.');
      const stored=await curioidVault.get(saved.id);
      if(!stored?.blob||Number(stored.size)!==byteLength)throw new Error('The saved project backup could not be read back with its original size.');
      if(await stored.blob.text()!==serialized)throw new Error('The saved project backup failed exact read-back verification.');
      window.dispatchEvent(new CustomEvent('curioid:vault-notice',{detail:{message:`Pre-import safety backup saved and verified: ${saved.name}.`} }));
      return {id:saved.id,name:saved.name,size:byteLength,createdAt};
    }catch(error){
      if(saved?.id)try{await curioidVault.remove(saved.id);}catch(_){}
      throw new Error(`CURIOID could not create and verify a durable project safety backup (${String(error?.message||error).slice(0,220)}). The replacement was not started.`);
    }
  }
  
  
  
