    const version=String(manifest.version||'1.0.0').trim().slice(0,32);if(!kernelConnectParseVersion(version))throw new Error('Version must use semantic versioning, for example 1.0.0.');
    const requiresKernel=String(manifest.requiresKernel||'1.3.0').trim();if(!kernelConnectParseVersion(requiresKernel))throw new Error('Required Kernel version must use semantic versioning, for example 1.3.0.');if(!kernelConnectSatisfies(CURIOID_KERNEL_VERSION,`>=${requiresKernel}`))throw new Error(`This OS requires CURIOID Kernel ${requiresKernel} or newer, but this website provides ${CURIOID_KERNEL_VERSION}.`);
    const requiresConnect=String(manifest.requiresConnect||'^1.0.0').trim().slice(0,100);if(!kernelConnectSatisfies(CURIOID_CONNECT_VERSION,requiresConnect))throw new Error(`This OS requires CURIOID Connect ${requiresConnect}, but this website provides ${CURIOID_CONNECT_VERSION}.`);
