    for(const [type,schema] of Object.entries(artifactContracts)){if(!artifactTypes.includes(type))throw new Error(`Artifact contract ${type} is not listed in artifactTypes.`);const problems=kernelConnectValidateSchemaDefinition(schema,`Artifact ${type} schema`);if(problems.length)throw new Error(problems.join(' '));}
    if(manifest.consumes!=null&&(!manifest.consumes||typeof manifest.consumes!=='object'||Array.isArray(manifest.consumes)))throw new Error('Required capabilities, artifact types, events and messages must be declared in a JSON object.');
    if(manifest.eventTypes!=null&&!Array.isArray(manifest.eventTypes))throw new Error('Provided event types must be a JSON array.');
