    const messageTypes=rawMessageTypes.map(item=>({id:item.id,version:String(item.version||'1.0.0'),access:item.access||'private',description:String(item.description||'').slice(0,240),schema:item.schema||{type:'object'},...(item.outputContract?{outputContract:item.outputContract}:{})}));
