          const artifact = await CurioidKernel.createArtifact({ sourceExperienceId: id, type: output.type, title: output.title, data: output.data, mediaType: output.mediaType, metadata: { ...output.metadata, nativeAdapter: id, adapterVersion: CurioidKernel.getAdapter(id)?.version || '1.0.0' } });
