          { id:'food-alchemy', name:'NOURISH' },
          { id:'echonoise-os', name:'EchoNoise' },
          { id:'umbra-os', name:'UMBRA' },
          { id:'aether-os', name:'Aether' },
          { id:'aura-synthesis', name:'AURA' }
