  // 51 - The Recipe Foundry: pairwise food discovery, draggable inventory and a persistent cookbook.
  
  const foodFusionRules = Object.create(null);
  const foodPairKey = (a,b) => [String(a),String(b)].sort().join('::');
  function addFoodRule(a,b,id,name,kind,summary,method,rarity='common') {
    foodFusionRules[foodPairKey(a,b)] = {id,name,kind,summary,method,rarity};
  }
  // A deliberately authored starter graph: useful kitchen transformations and recognizable dishes.
  addFoodRule('flour','water','dough','Dough','component','A simple, workable dough. This is the beginning of breads, pastries and noodles.','Mix flour with water gradually until a shaggy dough forms. Knead briefly until smooth, then rest covered.');
  addFoodRule('dough','heat','flatbread','Flatbread','dish','A simple flatbread cooked on a hot surface.','Divide the dough, roll it thin and cook on a hot dry pan, turning until both sides have browned spots.');
  addFoodRule('dough','yeast','risen-dough','Risen dough','component','A light, airy dough ready for a slower bake.','Work yeast into the dough, cover and leave in a warm place until visibly expanded.');
  addFoodRule('risen-dough','heat','loaf-bread','Fresh loaf','dish','A simple crusty loaf with a soft centre.','Shape the risen dough and bake in a fully preheated oven until deeply golden and hollow-sounding when tapped.');
  addFoodRule('flour','egg','pasta-dough','Fresh pasta dough','component','A rich dough that can become fresh pasta.','Combine flour and egg, knead until smooth, wrap and rest before rolling thinly.');
  addFoodRule('pasta-dough','heat','toasted-pasta-dough','Toasted pasta ribbons','component','A crisp, toasted pasta experiment.','Cut the dough into ribbons and toast gently until dry and lightly coloured.');
  addFoodRule('pasta','water','boiled-pasta','Cooked pasta','component','Pasta softened in simmering water and ready for a sauce.','Cook pasta in plenty of salted boiling water until just tender, then drain.');
  addFoodRule('tomato','garlic','tomato-garlic-sauce','Tomato and garlic sauce','component','A savoury base for pasta, toast and slow-cooked dishes.','Gently cook chopped garlic in olive oil, add tomato and simmer until thick and glossy.');
  addFoodRule('boiled-pasta','tomato-garlic-sauce','tomato-garlic-pasta','Tomato and garlic pasta','dish','A classic quick pasta built from a bright tomato sauce.','Toss the cooked pasta through the sauce with a splash of pasta water. Finish with herbs and black pepper.');
  addFoodRule('rice','water','rinsed-rice','Rinsed rice','component','Clean rice, ready for cooking.','Rinse the rice in cool water until the water is less cloudy, then drain well.');
  addFoodRule('rinsed-rice','heat','steamed-rice','Steamed rice','dish','Fluffy rice with separate grains.','Add the rice and measured water to a covered pot. Simmer gently until tender, then rest off the heat.');
  addFoodRule('tomato','onion','sofrito-base','Tomato and onion base','component','A savoury base for stews, sauces and baked dishes.','Soften chopped onion slowly, add tomato and cook until the mixture is thick and sweet.');
  addFoodRule('sofrito-base','chickpea','chickpea-tomato-stew','Chickpea and tomato stew','dish','A hearty, pantry-friendly stew with a rich tomato base.','Add cooked chickpeas and vegetable stock to the tomato base. Simmer until thick, then finish with herbs and lemon.');
  addFoodRule('chickpea','sesame','sesame-chickpea-mash','Sesame chickpea mash','component','A coarse chickpea and sesame preparation that can be seasoned into a dip.','Mash cooked chickpeas with toasted sesame, olive oil, lemon and a little water. For classic hummus, combine chickpeas with tahini instead.');
  addFoodRule('chickpea','tahini','hummus','Hummus','dish','A smooth chickpea dip enriched with tahini.','Blend cooked chickpeas with tahini, lemon juice, garlic, olive oil and enough cold water to make a creamy texture. Season to taste.');
  addFoodRule('chickpea','garlic','falafel-mix','Falafel mixture','component','A fragrant chickpea mixture ready to shape.','Mash cooked chickpeas with garlic, herbs and cumin. Add a little flour if needed to help the mixture hold together.');
  addFoodRule('falafel-mix','heat','falafel','Falafel patties','dish','Golden chickpea patties with herbs and warm spice.','Shape the mixture into small patties and bake or pan-fry until crisp and hot all the way through.');
  addFoodRule('potato','heat','baked-potato','Baked potato','dish','A fluffy potato with a crisp skin.','Scrub and dry the potato, prick the skin and bake until the centre is completely soft.');
  addFoodRule('potato','oil','crispy-potatoes','Crispy potatoes','dish','Golden potato pieces with crisp edges.','Cut potatoes into even pieces, coat lightly with oil and roast in a hot oven, turning once until crisp and tender.');
  addFoodRule('baked-potato','cheese','cheese-baked-potato','Cheese baked potato','dish','A baked potato finished with melted cheese.','Split the hot baked potato, fluff the centre and add cheese. Return briefly to the oven until melted.');
  addFoodRule('tomato','pepper','shakshuka-base','Shakshuka base','component','A gently spiced tomato and pepper pan sauce.','Soften pepper and onion, add chopped tomato, cumin and paprika, then simmer until thick.');
  addFoodRule('shakshuka-base','egg','shakshuka','Shakshuka','dish','Eggs gently cooked in a spiced tomato and pepper sauce.','Make small wells in the simmering sauce, add eggs, cover and cook until the whites are set.');
  addFoodRule('lentil','water','soaked-lentils','Soaked lentils','component','Lentils softened before cooking.','Rinse the lentils and soak briefly in cool water, then drain.');
