    const dialog=document.createElement('dialog');dialog.id='curioid-important-notes';dialog.className='curioid-notes-dialog';dialog.setAttribute('aria-labelledby','curioid-notes-title');dialog.setAttribute('aria-describedby','curioid-notes-intro');
    const panel=document.createElement('div');panel.className='curioid-notes-panel';
